// ===== lib/collection/src/operations/verification/mod.rs:297-348 (qdrant v1.18.0) =====
pub(crate) fn check_limit_opt<T: PartialOrd + Display>(
    value: Option<T>, limit: Option<T>, name: &str,
) -> CollectionResult<()> {
    let (Some(limit), Some(value)) = (limit, value) else {
        return Ok(());   // value None (key absent/ignored) => PASS
    };
    if value > limit {
        return Err(CollectionError::strict_mode(
            format!("Limit exceeded {value} > {limit} for \"{name}\""),
            format!("Reduce the \"{name}\" parameter to or below {limit}.")));
    }
    Ok(())
}

impl StrictModeVerification for SearchParams {
    async fn check_custom(&self, _collection: &Collection,
                           strict_mode_config: &StrictModeConfig) -> CollectionResult<()> {
        check_limit_opt(
            self.quantization.and_then(|i| i.oversampling),  // enforced knob: params.quantization.oversampling
            strict_mode_config.search_max_oversampling,
            "oversampling",
        )?;
        check_limit_opt(
            self.hnsw_ef,
            strict_mode_config.search_max_hnsw_ef,
            "hnsw_ef",
        )?;
        Ok(())
    }
}

// ===== lib/segment/src/types.rs:590-617 =====
pub struct SearchParams {
    pub hnsw_ef: Option<usize>,
    #[serde(default)] pub exact: bool,
    #[serde(default)] #[validate(nested)] pub quantization: Option<QuantizationSearchParams>, // ONLY holder of oversampling
    #[serde(default)] pub indexed_only: bool,
    #[serde(default)] #[validate(nested)] pub acorn: Option<AcornSearchParams>,
}   // NO top-level oversampling field; NO #[serde(deny_unknown_fields)] => unknown JSON keys silently ignored

// ===== lib/segment/src/types.rs:507-530 =====
pub struct QuantizationSearchParams {
    pub ignore: bool,
    pub rescore: Option<bool>,
    /// Oversampling factor for quantization. Default is 1.0.
    #[serde(default = "default_quantization_oversampling_value")]
    #[validate(range(min = 1.0))]
    pub oversampling: Option<f64>,
}

// ===== tests/openapi/test_strictmode.py:495-529 (Qdrant own integration test, same v1.18.0 tree) =====
def test_strict_mode_search_max_oversampling_validation(collection_name):
    ... body={"vector": [0.2,0.1,0.9,0.7], "limit": 4,
               "params": {"quantization": {"oversampling": 2.0}}}   # documented path
    set_strict_mode(collection_name, {"enabled": True, "search_max_oversampling": 2.0})
    search_request().raise_for_status()          # at cap => pass
    set_strict_mode(collection_name, {"enabled": True, "search_max_oversampling": 1.9})
    search_fail = search_request()
    assert "oversampling" in search_fail.json()['status']['error']  # above cap => REJECTED
    assert not search_fail.ok
